import { randomUUID } from "node:crypto";
import { rename, rm, writeFile } from "node:fs/promises";
import { basename, dirname, join } from "node:path";

const DEFAULT_FILE_OPERATIONS = { rename, rm, writeFile };

/**
 * Replace a file only after its complete contents have been written beside it.
 * Keeping the temporary file in the destination directory makes the final
 * rename atomic on the supported filesystems.
 */
export async function writeFileAtomic(
    target,
    contents,
    encoding = "utf8",
    fileOperations = DEFAULT_FILE_OPERATIONS
) {
    const temporary = join(
        dirname(target),
        `.${basename(target)}.${process.pid}.${randomUUID()}.tmp`
    );

    try {
        await fileOperations.writeFile(temporary, contents, encoding);
        await fileOperations.rename(temporary, target);
    } catch (error) {
        try {
            await fileOperations.rm(temporary, { force: true });
        } catch {
            // Preserve the write/rename error that made the operation fail.
        }
        throw error;
    }
}

// Produces the single-file mod the standalone (Steam) build loads.
//
// The dev build can fetch the mod over HTTP via externalModUrl, but the
// standalone reads plain .js files off disk, so the router has to be inlined
// ahead of time rather than at serve time.

import { readFile, mkdir } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { buildMod } from "../server/serve-mod.mjs";
import { writeFileAtomic } from "./atomic-write.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const OUT_DIR = process.argv[2] ? process.argv[2] : join(ROOT, "dist");
const OUT = join(OUT_DIR, "agent-bridge.js");

const source = await readFile(join(ROOT, "mod", "agent-bridge.js"), "utf8");
const built = await buildMod(source);

// Fail loudly rather than shipping a mod the game will reject at load time.
if (/^export\s/m.test(built)) throw new Error("build left an `export` in the output");
if (built.includes("@inject")) throw new Error("an @inject marker was not resolved");
if (!built.includes("class Mod")) throw new Error("no Mod class in the output");
if (!built.includes("const METADATA")) throw new Error("no METADATA in the output");
new Function(built); // parse check — catches syntax errors before the game does

await mkdir(OUT_DIR, { recursive: true });
await writeFileAtomic(OUT, built);
console.log(`Wrote ${OUT} (${built.length} bytes)`);

// Builds the mod and copies it into the shapez standalone's mods folder.
//
// The standalone reads every .js in %APPDATA%/shapez.io/mods at startup
// (electron/index.js:27), so installing is just dropping the built file there.

import { readFile, mkdir, access } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { buildMod } from "../server/serve-mod.mjs";
import { writeFileAtomic } from "./atomic-write.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");

function modsFolder() {
    if (process.env.SHAPEZ_MODS_DIR) return process.env.SHAPEZ_MODS_DIR;
    const roaming =
        process.env.APPDATA ||
        (process.platform === "darwin"
            ? join(process.env.HOME, "Library", "Preferences")
            : join(process.env.HOME, ".local", "share"));
    return join(roaming, "shapez.io", "mods");
}

const dir = modsFolder();
const target = join(dir, "agent-bridge.js");

const built = await buildMod(await readFile(join(ROOT, "mod", "agent-bridge.js"), "utf8"));
if (built.includes("@inject")) throw new Error("an @inject marker was not resolved");
new Function(built); // parse check before it reaches the game

try {
    await access(dir);
} catch {
    console.log(`Creating ${dir}`);
    await mkdir(dir, { recursive: true });
}

await writeFileAtomic(target, built);
console.log(`Installed ${target} (${built.length} bytes)`);
console.log("\nRestart shapez to load it. Delete that file to uninstall.");

// Runs every suite that doesn't need a running game.

import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const HERE = dirname(fileURLToPath(import.meta.url));
const SUITES = [
    ["belt router", "test-router.mjs"],
    ["bridge protocol", "test-protocol.mjs"],
    ["connect / port resolution", "test-connect.mjs"],
    ["agent loop", "test-agent-loop.mjs"],
    ["atomic file writes", "test-atomic-write.mjs"],
];

let failed = 0;
for (const [label, file] of SUITES) {
    console.log(`\n${"=".repeat(60)}\n  ${label}\n${"=".repeat(60)}`);
    const result = spawnSync(process.execPath, [join(HERE, file)], { stdio: "inherit" });
    if (result.status !== 0) failed++;
}

console.log(`\n${"=".repeat(60)}`);
console.log(failed ? `${failed} of ${SUITES.length} suites FAILED` : `All ${SUITES.length} suites passed`);
process.exit(failed ? 1 : 0);

import { mkdtemp, readFile, readdir, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { writeFileAtomic } from "./atomic-write.mjs";

let failures = 0;
let checks = 0;
function check(name, condition, extra = "") {
    checks++;
    if (!condition) failures++;
    console.log(`${condition ? "PASS" : "FAIL"}  ${name}${extra ? " — " + extra : ""}`);
}

const directory = await mkdtemp(join(tmpdir(), "shapez-agent-atomic-write-"));
const target = join(directory, "agent-bridge.js");

try {
    await writeFile(target, "known-good", "utf8");
    await writeFileAtomic(target, "complete-update");

    check("complete writes replace the target", (await readFile(target, "utf8")) === "complete-update");
    check(
        "successful writes leave no temporary file",
        (await readdir(directory)).every(name => !name.endsWith(".tmp"))
    );

    await writeFile(target, "known-good", "utf8");
    const expected = new Error("simulated interrupted write");
    const calls = [];
    const interruptedOperations = {
        async writeFile(path) {
            calls.push(["write", path]);
            throw expected;
        },
        async rename(from, to) {
            calls.push(["rename", from, to]);
        },
        async rm(path, options) {
            calls.push(["cleanup", path, options]);
        },
    };

    let thrown;
    try {
        await writeFileAtomic(target, "partial-update", "utf8", interruptedOperations);
    } catch (error) {
        thrown = error;
    }

    check("interrupted writes report their original error", thrown === expected);
    check("interrupted writes do not rename partial contents", !calls.some(([operation]) => operation === "rename"));
    check("interrupted writes clean up their temporary file", calls.some(([operation]) => operation === "cleanup"));
    check("interrupted writes preserve the installed mod", (await readFile(target, "utf8")) === "known-good");

    const renameError = new Error("simulated failed replacement");
    const renameOperations = {
        async writeFile(path, contents, encoding) {
            await writeFile(path, contents, encoding);
        },
        async rename() {
            throw renameError;
        },
        async rm(path, options) {
            await rm(path, options);
        },
    };

    thrown = undefined;
    try {
        await writeFileAtomic(target, "complete-but-not-installed", "utf8", renameOperations);
    } catch (error) {
        thrown = error;
    }

    check("failed replacements report the rename error", thrown === renameError);
    check("failed replacements preserve the installed mod", (await readFile(target, "utf8")) === "known-good");
    check(
        "failed replacements remove the completed temporary file",
        (await readdir(directory)).every(name => !name.endsWith(".tmp"))
    );
} finally {
    await rm(directory, { recursive: true, force: true });
}

console.log(`\n${checks} checks, ${failures} failures`);
process.exit(failures ? 1 : 0);
